diagram.source:
flowchart TD
  L[Left operand] --> Q{Operator?}
  Q -->|??| N{null or undefined?}
  N -->|yes| R[Return right]
  N -->|no| L2[Return left]
  Q -->|&#124;&#124;| F{falsy?}
  F -->|yes| R
  F -->|no| L2

snippet.code:
const count = 0;
console.log(count || 10);  // 10 — wrong for numeric 0
console.log(count ?? 10);  // 0 — correct

const label = "";
console.log(label || "default"); // "default"
console.log(label ?? "default"); // "" — empty string kept

const enabled = false;
console.log(enabled || true);  // true — false is falsy
console.log(enabled ?? true);  // false

function createServer(options = {}) {
  return {
    host: options.host ?? "0.0.0.0",
    port: options.port ?? 3000,
    maxBody: options.maxBody ?? 1_048_576,
  };
}

createServer({ port: 0 }); // port 0 valid — ?? keeps 0
// createServer({ port: null }); // 3000

// const x = 1 || 2 ?? 3; // SyntaxError
const x = (1 || 2) ?? 3; // 1
const y = 1 || (2 ?? 3); // 1

const ttl = config.cacheTtl ?? config.defaultTtl ?? 60;
